package dev.industrialtechnology.railway;
import java.util.*;import net.minecraft.world.World;import net.minecraftforge.event.entity.EntityJoinWorldEvent;import net.minecraftforge.event.world.WorldEvent;import cpw.mods.fml.common.eventhandler.SubscribeEvent;
public final class RailwayWorld {
 private static final Map<World,Map<UUID,EntityRollingStock>> worlds=new IdentityHashMap<>();public static void add(EntityRollingStock e){Map<UUID,EntityRollingStock> m=worlds.get(e.worldObj);if(m==null){m=new HashMap<>();worlds.put(e.worldObj,m);}m.put(e.getUniqueID(),e);}public static void remove(EntityRollingStock e){Map<UUID,EntityRollingStock> m=worlds.get(e.worldObj);if(m!=null&&m.get(e.getUniqueID())==e)m.remove(e.getUniqueID());}public static EntityRollingStock get(World w,UUID id){Map<UUID,EntityRollingStock> m=worlds.get(w);EntityRollingStock e=m==null||id==null?null:m.get(id);return e==null||e.isDead?null:e;}
 @SubscribeEvent public void join(EntityJoinWorldEvent e){if(e.entity instanceof EntityRollingStock){EntityRollingStock stock=(EntityRollingStock)e.entity;EntityRollingStock other=get(e.world,stock.getUniqueID());if(other!=null&&other!=stock&&!other.isDead){e.setCanceled(true);return;}add(stock);}}@SubscribeEvent public void chunk(net.minecraftforge.event.world.ChunkEvent.Unload e){for(java.util.List list:e.getChunk().entityLists)for(Object o:list)if(o instanceof EntityRollingStock)remove((EntityRollingStock)o);}
 @SubscribeEvent public void unload(WorldEvent.Unload e){worlds.remove(e.world);RailAudio.unload(e.world);}public static void clear(){worlds.clear();}
}
